#include <bits/stdc++.h>

using namespace std;

const int MAX_SIZE = 2345678;

double probabilities_real[123], probabilities[123];
double dynamic_prog[MAX_SIZE];
double results[123];
int indices[123];
int bit_counts[MAX_SIZE];

int main() {
    int total_real, max_k;
    scanf("%d %d", &total_real, &max_k);
    int valid_count = 0;
    for (int i = 0; i < total_real; i++) {
        scanf("%lf", probabilities_real + i);
        if (probabilities_real[i] > 1e-4) {
            indices[valid_count] = i;
            probabilities[valid_count] = probabilities_real[i];
            valid_count++;
        }
    }
    max_k = min(max_k, valid_count);
    bit_counts[0] = 0;
    for (int mask = 1; mask < (1 << valid_count); mask++) {
        bit_counts[mask] = bit_counts[mask & (mask - 1)] + 1;
    }
    for (int mask = 0; mask < (1 << valid_count); mask++) {
        dynamic_prog[mask] = 0.0;
    }
    for (int i = 0; i < total_real; i++) {
        results[i] = 0.0;
    }
    dynamic_prog[0] = 1.0;
    for (int mask = 0; mask < (1 << valid_count); mask++) {
        if (bit_counts[mask] == max_k) {
            for (int j = 0; j < valid_count; j++) {
                if (mask & (1 << j)) {
                    results[indices[j]] += dynamic_prog[mask];
                }
            }
            continue;
        }
        double total_prob = 0;
        for (int j = 0; j < valid_count; j++) {
            if (mask & (1 << j)) continue;
            total_prob += probabilities[j];
        }
        double q_value = dynamic_prog[mask] / total_prob;
        for (int j = 0; j < valid_count; j++) {
            if (mask & (1 << j)) continue;
            dynamic_prog[mask | (1 << j)] += probabilities[j] * q_value;
        }
    }
    for (int i = 0; i < total_real; i++) {
        if (i > 0) cout << " ";
        printf("%.17f", results[i]);
    }
    printf("\n");
    return 0;
}
